import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [threatData, setThreatData] = useState(null);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  // --- CHATBOT STATES ---
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatInput, setChatInput] = useState("");
  const [chatHistory, setChatHistory] = useState([
    { role: 'ai', text: 'Marhaba! I am CyberGuard AI. How can I help?', ar: 'مرحباً! أنا CyberGuard AI. كيف يمكنني مساعدتك؟' }
  ]);
  const chatEndRef = useRef(null);

  const [iotDevices, setIotDevices] = useState([
    { id: "IOT-RX-01", name: "Riyadh Hub", status: "Online", risk: "Low", firmware: "v2.1" },
    { id: "IOT-DXB-02", name: "Dubai Gateway", status: "Online", risk: "Low", firmware: "v2.0" },
    { id: "IOT-NEOM-03", name: "NEOM Sensor", status: "Online", risk: "Low", firmware: "v1.8" }
  ]);

  // Chat scroll logic
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [chatHistory]);

  const discoverNewDevice = () => {
    const regions = ["Riyadh", "Dubai", "Abu Dhabi", "NEOM", "Jeddah"];
    const types = ["Camera", "Power Grid", "Water Sensor", "Smart Light", "Traffic Monitor"];
    const newDevice = {
      id: `IOT-${Math.floor(Math.random() * 9000 + 1000)}`,
      name: `${regions[Math.floor(Math.random() * regions.length)]} ${types[Math.floor(Math.random() * types.length)]}`,
      status: "Online",
      risk: Math.random() > 0.8 ? "Medium" : "Low",
      firmware: "v1." + Math.floor(Math.random() * 9)
    };
    setIotDevices(prev => [newDevice, ...prev].slice(0, 10));
  };

  const fetchThreats = async () => {
    try {
      let testPayload = "normal_traffic";
      let testIp = `192.168.1.${Math.floor(Math.random() * 255)}`;
      let testRequests = Math.floor(Math.random() * 300); 
      let testSize = Math.floor(Math.random() * 2000);
      const randomVal = Math.random();

      if (randomVal > 0.8) {
        testPayload = "UNION SELECT * FROM users--";
        testIp = "HACKER_SQL_INJECT"; 
      } else if (randomVal > 0.6) {
        testRequests = 900; testSize = 150;
        testIp = "10.0.0." + Math.floor(Math.random() * 100);
      }

      const res = await axios.post('http://localhost:8000/analyze-traffic', {
        ip_source: testIp, packet_size: testSize, request_count: testRequests, payload: testPayload
      });

      setThreatData(res.data);
      setLoading(false);

      if (res.data.is_anomaly) {
        setAlerts(prev => [{ id: Date.now(), ...res.data, time: new Date().toLocaleTimeString() }, ...prev].slice(0, 6));
      }
    } catch (err) { console.error("Error", err); }
  };

  // --- CHATBOT SEND LOGIC ---
  const handleSendMessage = async () => {
    if (!chatInput.trim()) return;

    const userMsg = { role: 'user', text: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput("");

    try {
      const res = await axios.post('http://localhost:8000/chat', { message: chatInput });
      const aiMsg = { role: 'ai', text: res.data.reply_en, ar: res.data.reply_ar };
      setChatHistory(prev => [...prev, aiMsg]);
    } catch (err) {
      setChatHistory(prev => [...prev, { role: 'ai', text: 'Error connecting to JAIS AI.', ar: 'خطأ في الاتصال' }]);
    }
  };

  useEffect(() => {
    const discoveryTimer = setInterval(discoverNewDevice, 10000);
    const threatTimer = setInterval(fetchThreats, 5000);
    return () => { clearInterval(discoveryTimer); clearInterval(threatTimer); };
  }, []);

  return (
    <div style={{ backgroundColor: '#010409', color: '#c9d1d9', minHeight: '100vh', padding: '25px', fontFamily: 'Arial, sans-serif', position: 'relative' }}>

      {/* HEADER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #30363d', paddingBottom: '15px' }}>
        <h2 style={{ color: '#58a6ff', margin: 0 }}>🛡️ CyberGuard AI | Vision 2030 SOC Monitor</h2>
        <div style={{ textAlign: 'right', fontSize: '12px' }}>
          <span style={{ color: '#3fb950' }}>● AI ENGINE ACTIVE</span> | UAE-KSA REGION
        </div>
      </div>

      {/* IoT Assets */}
      <h3 style={{ marginTop: '25px', fontSize: '18px', color: '#8b949e' }}>🌐 IoT Infrastructure Assets (Live Discovery)</h3>
      <div style={{ display: 'flex', overflowX: 'auto', gap: '15px', padding: '10px 0' }}>
        {iotDevices.map(device => (
          <div key={device.id} style={{ minWidth: '200px', background: '#0d1117', border: '1px solid #30363d', padding: '15px', borderRadius: '8px', borderLeft: `5px solid ${device.risk === 'Low' ? '#3fb950' : '#f85149'}` }}>
            <strong>{device.name}</strong><br/>
            <small style={{ color: '#8b949e' }}>{device.id} | FW: {device.firmware}</small>
          </div>
        ))}
      </div>

      {/* Analysis Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginTop: '30px' }}>
        <div style={{ background: '#161b22', border: '1px solid #30363d', padding: '20px', borderRadius: '10px' }}>
          <h4 style={{ margin: '0 0 10px 0' }}>Traffic Analysis Node</h4>
          {!loading && (
            <p style={{ fontSize: '18px', color: threatData.is_anomaly ? '#f85149' : '#3fb950' }}>
              {threatData.is_anomaly ? '⚠️ ANOMALY: ' : '✅ SECURE: '} {threatData.location.toUpperCase()}
            </p>
          )}
        </div>
        <div style={{ background: '#161b22', border: '1px solid #30363d', padding: '20px', borderRadius: '10px' }}>
          <h4 style={{ margin: '0 0 10px 0' }}>Defense Response</h4>
          <p>Recommendation: <strong>{threatData?.recommendation || 'Monitoring...'}</strong></p>
        </div>
      </div>

      {/* THREAT TABLE */}
      <div style={{ marginTop: '30px', background: '#0d1117', border: '1px solid #30363d', borderRadius: '10px', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead style={{ background: '#161b22', textAlign: 'left', color: '#8b949e' }}>
            <tr>
              <th style={{ padding: '12px' }}>Time</th>
              <th style={{ padding: '12px' }}>Incident</th>
              <th style={{ padding: '12px' }}>Origin</th>
              <th style={{ padding: '12px' }}>Arabic (JAIS)</th>
            </tr>
          </thead>
          <tbody>
            {alerts.map(alert => (
              <tr key={alert.id} style={{ borderBottom: '1px solid #21262d' }}>
                <td style={{ padding: '12px', fontSize: '12px' }}>{alert.time}</td>
                <td style={{ padding: '12px' }}>{alert.analysis_report}</td>
                <td style={{ padding: '12px', fontSize: '11px', color: '#58a6ff' }}>{alert.ip_source}</td>
                <td style={{ padding: '12px', direction: 'rtl', textAlign: 'right', color: '#8b949e' }}>{alert.arabic_report}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* --- FLOATING CHATBOT UI --- */}
      <div style={{ position: 'fixed', bottom: '20px', right: '20px', zIndex: 1000 }}>
        {!isChatOpen ? (
          <button 
            onClick={() => setIsChatOpen(true)}
            style={{ width: '60px', height: '60px', borderRadius: '50%', background: '#58a6ff', border: 'none', cursor: 'pointer', fontSize: '24px', boxShadow: '0 4px 15px rgba(0,0,0,0.3)' }}
          >
            🤖
          </button>
        ) : (
          <div style={{ width: '350px', height: '450px', background: '#161b22', border: '1px solid #30363d', borderRadius: '15px', display: 'flex', flexDirection: 'column', boxShadow: '0 8px 25px rgba(0,0,0,0.5)' }}>
            <div style={{ padding: '15px', background: '#0d1117', borderBottom: '1px solid #30363d', display: 'flex', justifyContent: 'space-between', borderRadius: '15px 15px 0 0' }}>
              <strong>JAIS AI Assistant</strong>
              <button onClick={() => setIsChatOpen(false)} style={{ background: 'none', border: 'none', color: '#8b949e', cursor: 'pointer' }}>✕</button>
            </div>

            <div style={{ flex: 1, overflowY: 'auto', padding: '15px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {chatHistory.map((msg, i) => (
                <div key={i} style={{ alignSelf: msg.role === 'user' ? 'flex-end' : 'flex-start', background: msg.role === 'user' ? '#1f6feb' : '#30363d', padding: '8px 12px', borderRadius: '10px', maxWidth: '80%', fontSize: '13px' }}>
                  {msg.text}
                  {msg.ar && <div style={{ direction: 'rtl', borderTop: '1px solid #444', marginTop: '5px', paddingTop: '5px', fontSize: '11px', color: '#8b949e' }}>{msg.ar}</div>}
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div style={{ padding: '10px', display: 'flex', gap: '5px' }}>
              <input 
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
                placeholder="Ask AI (Status, Attacks...)"
                style={{ flex: 1, background: '#0d1117', border: '1px solid #30363d', color: 'white', padding: '8px', borderRadius: '5px', outline: 'none' }}
              />
              <button onClick={handleSendMessage} style={{ background: '#238636', border: 'none', color: 'white', padding: '8px 12px', borderRadius: '5px', cursor: 'pointer' }}>Send</button>
            </div>
          </div>
        )}
      </div>

    </div>
  );
};

export default Dashboard;
